param([ValidateSet('Light','Full')][string]$Mode,[ValidateSet('Main','Remote')][string]$NodeRole='Main')
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$mutex=[Threading.Mutex]::new($false,'Local\AevryndQwenModeSwitch');$held=$mutex.WaitOne(30000);if(-not$held){throw 'Mode switch lock timeout.'};try{if($Mode-eq'Full'){if($NodeRole-eq'Main'){throw 'Full mode is forbidden on the main computer.'};throw 'Remote full-mode controller is not configured; existing 27B service was not modified.'};& (Join-Path $PSScriptRoot 'Start-Light.ps1')}finally{if($held){$mutex.ReleaseMutex()};$mutex.Dispose()}
